import{_ as e,o as d,c as r,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const f=JSON.parse('{"title":"mini-proxy 与生产代理的差异","description":"","frontmatter":{"title":"mini-proxy 与生产代理的差异"},"headers":[],"relativePath":"proxy-software-course/divergence.md","filePath":"proxy-software-course/docs/divergence.md"}'),o={name:"proxy-software-course/divergence.md"};function h(n,t,l,c,i,s){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="mini-proxy-与生产代理的差异" tabindex="-1">mini-proxy 与生产代理的差异 <a class="header-anchor" href="#mini-proxy-与生产代理的差异" aria-label="Permalink to &quot;mini-proxy 与生产代理的差异&quot;">​</a></h1><p>本页汇总正文与 <code>companion/README.md</code> 中出现过的全部教学简化与未实现能力，每条都标注它在正文里的出处，方便和 <a href="./protocol-reference.html">协议字节与响应码速查</a> 互相对账。</p><h2 id="http-正向代理层面的简化" tabindex="-1">HTTP 正向代理层面的简化 <a class="header-anchor" href="#http-正向代理层面的简化" aria-label="Permalink to &quot;HTTP 正向代理层面的简化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>简化项</th><th>说明</th><th>出处</th></tr></thead><tbody><tr><td>不支持 keep-alive / 请求流水线</td><td>一条 TCP 连接只处理一个请求或一条 CONNECT 隧道，处理完即结束，不复用连接处理下一个请求</td><td><a href="./02-http-forward-proxy.html">第 2 章</a></td></tr><tr><td>body framing 简化</td><td>不解析任何消息体边界：<code>Content-Length</code> 与 chunked framing 都不校验，头部之后的字节交给 <code>relay</code> 原样转发</td><td><a href="./02-http-forward-proxy.html">第 2 章</a></td></tr></tbody></table><h2 id="socks5-层面未实现的能力" tabindex="-1">SOCKS5 层面未实现的能力 <a class="header-anchor" href="#socks5-层面未实现的能力" aria-label="Permalink to &quot;SOCKS5 层面未实现的能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>未实现项</th><th>说明</th><th>出处</th></tr></thead><tbody><tr><td>认证方式仅 NO AUTH</td><td>不支持用户名密码等其他 METHOD</td><td><a href="./03-socks5-protocol.html">第 3 章</a>、<a href="./protocol-reference.html">协议速查</a></td></tr><tr><td>命令仅 CONNECT</td><td><code>BIND</code>、<code>UDP ASSOCIATE</code> 按 RFC 1928 回 <code>COMMAND_NOT_SUPPORTED</code> 后关闭连接，不做实际实现</td><td><a href="./03-socks5-protocol.html">第 3 章</a></td></tr><tr><td>无 UDP 数据通道</td><td>UDP ASSOCIATE 命令本身既不解析也不建立数据通道</td><td><a href="./03-socks5-protocol.html">第 3 章</a></td></tr></tbody></table><h2 id="规则与-dns-层面的简化" tabindex="-1">规则与 DNS 层面的简化 <a class="header-anchor" href="#规则与-dns-层面的简化" aria-label="Permalink to &quot;规则与 DNS 层面的简化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>简化项</th><th>说明</th><th>出处</th></tr></thead><tbody><tr><td>IP-CIDR 仅支持 IPv4</td><td>不解析、不匹配 IPv6 CIDR 网段</td><td><a href="./05-rule-engine.html">第 5 章</a>、<a href="./protocol-reference.html">协议速查</a></td></tr><tr><td>DNS 简化为可注入的 <code>Resolver</code></td><td>只返回单个 IP，不做多地址轮询、TTL 缓存或真实的递归解析细节；测试全程注入固定假 resolver</td><td><a href="./06-dns-strategy.html">第 6 章</a>、<a href="./09-runtime-assembly.html">第 9 章</a></td></tr><tr><td>无 DNS over HTTPS/TLS、无 DNS 层面的隐私保护</td><td><code>defaultResolver</code> 只是对 <code>dns.lookup</code> 的直接封装</td><td><a href="./06-dns-strategy.html">第 6 章</a></td></tr></tbody></table><h2 id="网络层接管与出站层面的简化" tabindex="-1">网络层接管与出站层面的简化 <a class="header-anchor" href="#网络层接管与出站层面的简化" aria-label="Permalink to &quot;网络层接管与出站层面的简化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>未实现项</th><th>说明</th><th>出处</th></tr></thead><tbody><tr><td>无 TUN / 系统级流量接管</td><td>只处理主动连接到监听端口的流量，不创建虚拟网卡、不修改路由表</td><td><a href="./01-proxy-mental-model.html">第 1 章</a>、<a href="./10-end-to-end-boundary.html">第 10 章</a></td></tr><tr><td>无加密出站 / 无流量混淆</td><td>DIRECT 与上游 SOCKS5 均为明文 TCP，没有可选 TLS 出站，也不做任何流量特征伪装</td><td><a href="./10-end-to-end-boundary.html">第 10 章</a></td></tr></tbody></table><h2 id="运行时与安全层面未实现的能力" tabindex="-1">运行时与安全层面未实现的能力 <a class="header-anchor" href="#运行时与安全层面未实现的能力" aria-label="Permalink to &quot;运行时与安全层面未实现的能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>未实现项</th><th>说明</th><th>出处</th></tr></thead><tbody><tr><td>无认证 / 访问控制</td><td><code>createHttpForwardServer</code>、<code>createSocks5Server</code> 不校验&quot;谁在发起连接&quot;，本质是一个开放代理</td><td><a href="./10-end-to-end-boundary.html">第 10 章</a></td></tr><tr><td>无资源上限治理</td><td>没有单连接/单客户端限流、超时回收、内存或文件描述符上限</td><td><a href="./10-end-to-end-boundary.html">第 10 章</a></td></tr><tr><td>无生产级可观测性</td><td>只有结构化事件回调（<code>type</code> + <code>detail</code>），没有日志分级、指标导出或链路追踪</td><td><a href="./09-runtime-assembly.html">第 9 章</a>、<a href="./10-end-to-end-boundary.html">第 10 章</a></td></tr><tr><td>无配置热重载</td><td>配置只在启动时解析一次，运行中修改配置文件不会生效，需要重启进程</td><td><a href="./08-runtime-config.html">第 8 章</a>、<a href="./09-runtime-assembly.html">第 9 章</a></td></tr><tr><td>无平台集成</td><td>交付形态是一个 Node.js 进程 + JSON 配置 + CLI，没有系统服务管理、多平台安装包或 GUI</td><td><a href="./10-end-to-end-boundary.html">第 10 章</a></td></tr><tr><td>错误映射简化</td><td>拨号失败、规则拒绝等情况统一用字符串 <code>reason</code> 表达（如 <code>direct dial failed: ...</code>、<code>rejected by rule</code>），不是完整的错误码/错误类型体系</td><td><a href="./07-outbound-adapters.html">第 7 章</a></td></tr></tbody></table><p>以上全部是这门课程明确划定、<strong>未在课程范围内实现</strong>的能力，不是遗漏；第 10 章的生产差异表和边界声明是这份清单的正文来源。</p>',13)])])}const b=e(o,[["render",h]]);export{f as __pageData,b as default};
